function teamForm(t=null){
 if(t&&!isAdmin())return toast('Somente o ADM pode editar times por este formulário.','err');
 const m=modal(t?'Editar time':'Criar time',`<form id="teamForm"><div class="grid two"><div class="field"><div class="label">Nome do time</div><input id="tn" class="input" maxlength="65" minlength="3" required value="${esc(t?.name||'')}"></div><div class="field"><div class="label">Tag</div><input id="tt" class="input" maxlength="8" minlength="2" required value="${esc(t?.tag||'')}"></div></div><div class="field"><div class="label">Dono do time</div><input class="input" disabled value="${esc(t?(profileBy(t.created_by)?.nickname||'Não identificado'):(state.profile.nickname||state.profile.full_name))}"></div><div class="field"><div class="label">Divisão</div>${t&&isAdmin()?`<select id="td" class="select">${['Divisão A','Divisão B'].map(d=>`<option ${t.division===d?'selected':''}>${d}</option>`).join('')}</select>`:`<input class="input" disabled value="Divisão B (alterável pelo ADM)">`}</div><div class="field"><div class="label">Descrição</div><textarea id="tds" class="textarea" maxlength="1500">${esc(t?.description||'')}</textarea></div><button class="btn primary" type="submit">${t?'Salvar alterações':'Criar meu time'}</button></form>`);
 $('#teamForm',m).onsubmit=async e=>{e.preventDefault();const btn=$('button[type=submit]',m);btn.disabled=true;try{
  const name=$('#tn',m).value.trim(),tag=$('#tt',m).value.trim().toUpperCase(),description=$('#tds',m).value.trim();
  if(t)await update('teams',t.id,{name,tag,description,division:$('#td',m).value});
  else await api('/rest/v1/rpc/create_owned_team',{method:'POST',body:JSON.stringify({p_name:name,p_tag:tag,p_description:description})});
  m.remove();await reload();toast(t?'Time atualizado':'Time criado e vinculado à sua conta!');
 }catch(err){toast(err.message,'err')}finally{btn.disabled=false}}
}
function openTeam(id){
 const t=teamBy(id);if(!t)return;
 const s=statsBy(id),ranking=state.scrimRanking.find(r=>r.team_id===id),members=state.members.filter(x=>x.team_id===id);
 const me=members.find(x=>x.profile_id===state.profile.id),canStaff=isAdmin()||['staff','coach','manager'].includes(me?.team_role);
 const owner=profileBy(t.created_by),isOwner=t.created_by===state.profile.id;
 const m=modal(t.name,`<div class="team-detail-head"><div class="team-logo big">${esc(t.tag)}</div><div><h3>${esc(t.division)} · ${tierBadge(t.team_tier)}</h3><p>${esc(t.description||'')}</p><div class="muted small">Dono: <strong>${esc(owner?.nickname||owner?.full_name||'Não identificado')}</strong></div></div></div><div class="grid four compact-stats"><div><b>${ranking?.games||0}</b><span>Scrims</span></div><div><b>${ranking?.wins||0}</b><span>Vitórias</span></div><div><b>${formatPts(ranking?.points||0)}</b><span>Pontos</span></div><div><b>✦ ${s.reputation??50}</b><span>Reputação</span></div></div><div class="section-title"><h2>Integrantes</h2>${isAdmin()?'<button class="btn ghost" id="addMember">Adicionar</button>':''}</div><div class="member-list">${members.length?members.map(x=>{const p=profileBy(x.profile_id);return `<div class="member-row"><div class="avatar">${p?.avatar_url?`<img src="${esc(p.avatar_url)}">`:initials(p?.nickname||p?.full_name)}</div><div class="grow"><strong>${esc(p?.nickname||p?.full_name||'Usuário')}</strong><span>${esc(x.team_role)}</span></div>${x.opgg_url?`<a class="btn ghost" target="_blank" rel="noopener" href="${esc(x.opgg_url)}">OP.GG</a>`:''}${canStaff?`<button class="btn ghost" data-opgg="${x.id}">Editar OP.GG</button>`:''}${isAdmin()?`<button class="btn danger" data-rm-member="${x.id}">Remover</button>`:''}</div>`}).join(''):'<div class="muted">Nenhum integrante.</div>'}</div><div class="card-actions">${isOwner?'<button class="btn primary" id="inviteFromTeam">Convidar para scrim</button>':''}${isAdmin()?'<button class="btn ghost" id="editTeam">Editar time e divisão</button><button class="btn danger" id="deleteTeam">Excluir time</button>':''}</div>`);
 $('#inviteFromTeam',m)?.addEventListener('click',()=>{m.remove();openScrimInvite(id)});
 $('#editTeam',m)?.addEventListener('click',()=>{m.remove();teamForm(t)});
 $('#deleteTeam',m)?.addEventListener('click',async()=>{if(confirm('Excluir este time e seus vínculos?')){try{await remove('teams',id);m.remove();await reload()}catch(e){toast(e.message,'err')}}});
 $('#addMember',m)?.addEventListener('click',()=>addMemberForm(id,m));
 $$('[data-rm-member]',m).forEach(b=>b.onclick=async()=>{try{await remove('team_members',b.dataset.rmMember);m.remove();await reload();openTeam(id)}catch(e){toast(e.message,'err')}});
 $$('[data-opgg]',m).forEach(b=>b.onclick=()=>editOpgg(b.dataset.opgg,id,m));
}
function addMemberForm(teamId,parent){const options=state.profiles.filter(p=>!state.members.some(m=>m.team_id===teamId&&m.profile_id===p.id));const m=modal('Adicionar integrante',`<form id="memberForm"><div class="field"><div class="label">Usuário</div><select id="mp" class="select" required>${options.map(p=>`<option value="${p.id}">${esc(p.nickname||p.full_name||p.email)}</option>`).join('')}</select></div><div class="field"><div class="label">Função no time</div><select id="mr" class="select"><option value="player">Jogador</option><option value="staff">Staff</option><option value="coach">Coach</option><option value="manager">Manager</option></select></div><div class="field"><div class="label">Link OP.GG</div><input id="mo" class="input" type="url" required placeholder="https://op.gg/..."></div><button class="btn primary">Adicionar</button></form>`);$('#memberForm',m).onsubmit=async e=>{e.preventDefault();try{await insert('team_members',{team_id:teamId,profile_id:$('#mp',m).value,team_role:$('#mr',m).value,opgg_url:$('#mo',m).value.trim()||null});m.remove();parent.remove();await reload();openTeam(teamId)}catch(err){toast(err.message,'err')}}}
